 "content": "def transform(grid):
    # Extract the largest 4-connected nonzero component, which is the canvas.
    h, w = len(grid), len(grid[0])
    seen, largest = set(), []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0 or (i, j) in seen:
                continue
            stack, component = [(i, j)], []
            seen.add((i, j))
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and grid[a][b] != 0 and (a, b) not in seen:
                        seen.add((a, b))
                        stack.append((a, b))
            if len(component) > len(largest):
                largest = component
    top, bottom = min(i for i, _ in largest), max(i for i, _ in largest)
    left, right = min(j for _, j in largest), max(j for _, j in largest)
    return [row[left:right + 1] for row in grid[top:bottom + 1]]
