 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    largest = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            comp, stack = [], [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dr, y + dc
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(comp) > len(largest):
                largest = comp

    board_cells = set(largest)
    top, bottom = min(r for r, _ in largest), max(r for r, _ in largest)
    left, right = min(c for _, c in largest), max(c for _, c in largest)
    outside = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != 0 and (r, c) not in board_cells]
    key_colors = {v for _, _, v in outside}

    # Clear the three marked cells before transposing the patterned board.
    board = [row[left:right + 1] for row in grid[top:bottom + 1]]
    for r, c in largest:
        if grid[r][c] in key_colors:
            board[r - top][c - left] = 1
    out = [list(row) for row in zip(*board)]

    # The isolated guide dots encode marker colors and their output positions.
    if outside:
        min_r = min(r for r, _, _ in outside)
        min_c = min(c for _, c, _ in outside)
        for r, c, color in outside:
            rr, cc = r - min_r, c - min_c
            if rr < len(out) and cc < len(out[0]):
                out[rr][cc] = color
    return out
