 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The board is the largest connected nonzero component; outside dots form
    # a 2x2 corner pattern whose missing corner determines the symmetry.
    seen, largest = set(), []
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            comp, stack = [], [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dr, y + dc
                    if 0 <= a < h and 0 <= b < w and grid[a][b] and (a, b) not in seen:
                        seen.add((a, b)); stack.append((a, b))
            if len(comp) > len(largest):
                largest = comp
    top, bottom = min(r for r, _ in largest), max(r for r, _ in largest)
    left, right = min(c for _, c in largest), max(c for _, c in largest)
    board = [row[left:right + 1] for row in grid[top:bottom + 1]]
    occupied = set(largest)
    guides = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] and (r, c) not in occupied}
    rr, cc = sorted({r for r, _ in guides}), sorted({c for _, c in guides})
    missing = next((r, c) for r in rr for c in cc if (r, c) not in guides)

    # Missing corner indicates transformations; examples establish:
    # bottom-right -> transpose, bottom-left -> transpose then vertical flip,
    # top-left -> vertical flip, top-right -> horizontal flip.
    if missing == (rr[1], cc[1]):
        return [list(row) for row in zip(*board)]
    if missing == (rr[1], cc[0]):
        return [list(row) for row in zip(*board[::-1])]
    if missing == (rr[0], cc[0]):
        return board[::-1]
    return [row[::-1] for row in board]
